-- evt:mask_chop
RegisterEvent(24, "Toll-keeper", function(continueStep)
    local eventId = 24
    if continueStep == 1 then
        if XeenQuests.hook("m40.mask_chopping") then evt.PlaySoundName("gold01") end
        return
    end
    if continueStep == 3 then XeenQuests.hook("m40.mask_clue") return end
    if continueStep == 2 or continueStep == 4 then XeenQuests.hook("m40.mask_no") return end
    if continueStep ~= nil then return end
    if IsQBitSet(QBit(118117)) then
        AskChoiceWithAnswerSteps(eventId, 6, "\"For another 500 I'll give you a clue. Will you pay?\"", {{Answer = "Yes", Step = 3}, {Answer = "No", Step = 4}})
        return
    end
    AskChoiceWithAnswerSteps(eventId, 5, "\"For 2,000 gold I can protect you from the Chopping Death. Will you pay?\"", {{Answer = "Yes", Step = 1}, {Answer = "No", Step = 2}})
end, "Toll-keeper")

